import json
import yaml

# ============================================================
# 1. Read the success experiments JSON
# ============================================================
with open('/tmp/registry_success_summary.json', 'r') as f:
    content = f.read()
    json_start = content.index('[')
    experiments = json.loads(content[json_start:])

# Sort by exp_id
experiments.sort(key=lambda x: x['exp_id'])

# ============================================================
# Helper: extract key metric from metrics dict
# ============================================================
def get_key_metric(m):
    """Return (metric_name, value) for the most important metric."""
    if not m:
        return ("—", "—")

    # Priority order for key metric
    priority_keys = [
        'accuracy', 'overall_accuracy',
        'f1_macro', 'pass_f1', 'fail_f1',
        'pooled_gap_pp', 'icc',
        'accuracy_greedy', 'accuracy_majority_vote_K3',
        'overall_block_adv',
    ]

    for k in priority_keys:
        if k in m:
            v = m[k]
            if isinstance(v, (int, float)):
                return (k, v)

    # If metrics has nested dicts (like multi-seed), try to summarize
    if 'mean' in m and isinstance(m['mean'], dict):
        if 'accuracy' in m['mean']:
            return ('mean_accuracy', m['mean']['accuracy'])

    # Fallback: first numeric value
    for k, v in m.items():
        if isinstance(v, (int, float)):
            return (k, v)

    # Check nested
    for k, v in m.items():
        if isinstance(v, dict):
            for k2, v2 in v.items():
                if 'accuracy' in k2.lower() and isinstance(v2, (int, float)):
                    return (f"{k}.{k2}", v2)

    return ("—", "—")

def truncate(s, maxlen=80):
    s = s.replace('\n', ' ').strip()
    if len(s) > maxlen:
        return s[:maxlen-3] + '...'
    return s

# ============================================================
# 2. Build markdown table
# ============================================================
lines = []
lines.append("# All Success Experiments (132)")
lines.append("")
lines.append("| # | exp_id | key_metric | value | hypothesis | tags |")
lines.append("|---|--------|-----------|-------|-----------|------|")

for i, exp in enumerate(experiments, 1):
    eid = exp['exp_id']
    metric_name, metric_val = get_key_metric(exp.get('metrics', {}))
    if isinstance(metric_val, float):
        metric_val_str = f"{metric_val:.2f}" if metric_val < 1 else f"{metric_val}"
    else:
        metric_val_str = str(metric_val)
    hyp = truncate(exp.get('hypothesis', '—'), 90)
    tags = ', '.join(exp.get('tags', [])) if exp.get('tags') else '—'
    lines.append(f"| {i} | {eid} | {metric_name} | {metric_val_str} | {hyp} | {tags} |")

md_content = '\n'.join(lines) + '\n'

with open('/tmp/all_success_experiments.md', 'w') as f:
    f.write(md_content)

print(f"Written {len(experiments)} experiments to /tmp/all_success_experiments.md")

# ============================================================
# 3. Build metrics lookup JSON
# ============================================================
def extract_numeric_metrics(m, prefix=""):
    """Recursively extract all numeric metrics."""
    result = {}
    if not isinstance(m, dict):
        return result
    for k, v in m.items():
        full_key = f"{prefix}{k}" if not prefix else f"{prefix}.{k}"
        if isinstance(v, (int, float)):
            result[full_key] = v
        elif isinstance(v, dict):
            result.update(extract_numeric_metrics(v, full_key))
    return result

metrics_lookup = {}
for exp in experiments:
    eid = exp['exp_id']
    raw = exp.get('metrics', {})
    if raw:
        flat = extract_numeric_metrics(raw)
        if flat:
            metrics_lookup[eid] = flat

with open('/tmp/exp_metrics_lookup.json', 'w') as f:
    json.dump(metrics_lookup, f, indent=2)

print(f"Written {len(metrics_lookup)} experiment metrics to /tmp/exp_metrics_lookup.json")

# ============================================================
# 4. Read registry.yaml for negative/failed experiments
# ============================================================
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_16/projects/exec-sim-repair-verifier/registry.yaml', 'r') as f:
    registry = yaml.safe_load(f)

exps = registry.get('experiments', {})
neg_failed = {}
for eid, edata in exps.items():
    conclusion = edata.get('conclusion', '')
    if conclusion in ('negative', 'failed'):
        neg_failed[eid] = edata

print(f"\nFound {len(neg_failed)} negative/failed experiments in registry.yaml")
for eid in sorted(neg_failed.keys()):
    print(f"  [{neg_failed[eid].get('conclusion')}] {eid}")

# Build negative experiments markdown
neg_lines = []
neg_lines.append("# Negative/Failed Experiments")
neg_lines.append("")
neg_lines.append(f"Total: {len(neg_failed)} experiments")
neg_lines.append("")
neg_lines.append("| # | exp_id | conclusion | hypothesis | key_metric | notes |")
neg_lines.append("|---|--------|-----------|-----------|-----------|-------|")

for i, eid in enumerate(sorted(neg_failed.keys()), 1):
    edata = neg_failed[eid]
    conclusion = edata.get('conclusion', '—')
    hyp = truncate(str(edata.get('hypothesis', '—')), 80)
    metrics = edata.get('metrics', {})
    metric_name, metric_val = get_key_metric(metrics) if metrics else ("—", "—")
    if isinstance(metric_val, float):
        metric_str = f"{metric_name}={metric_val:.2f}" if metric_val < 1 else f"{metric_name}={metric_val}"
    elif metric_val != "—":
        metric_str = f"{metric_name}={metric_val}"
    else:
        metric_str = "—"
    notes = truncate(str(edata.get('notes', '—')), 100)
    neg_lines.append(f"| {i} | {eid} | {conclusion} | {hyp} | {metric_str} | {notes} |")

neg_md = '\n'.join(neg_lines) + '\n'

with open('/tmp/negative_experiments.md', 'w') as f:
    f.write(neg_md)

print(f"\nWritten {len(neg_failed)} negative/failed experiments to /tmp/negative_experiments.md")

